-- Generated by tools/c45_supabase_migrate/bin/promote_drafts.dart

-- S14 US-01/US-02: self-only profile update. User resolved from auth.uid().
-- Empty names are stored as null. Login email is not accepted or modified here.
create or replace function iam.update_my_platform_user_profile(
  p_avatar_reference text,
  p_given_name text,
  p_family_name text,
  p_phone text
)
returns jsonb
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_given text := nullif(trim(coalesce(p_given_name, '')), '');
  v_family text := nullif(trim(coalesce(p_family_name, '')), '');
  v_phone text := nullif(trim(coalesce(p_phone, '')), '');
  v_avatar text := nullif(trim(coalesce(p_avatar_reference, '')), '');
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  if v_avatar is not null and length(v_avatar) > 512 then
    raise exception 'invalid avatar reference';
  end if;

  insert into iam.platform_user_profiles (
    user_id, given_name, family_middle_name, phone_number, avatar_reference,
    created_at, updated_at
  )
  values (
    v_user_id, v_given, v_family, v_phone, v_avatar,
    now(), now()
  )
  on conflict (user_id) do update
    set given_name = excluded.given_name,
        family_middle_name = excluded.family_middle_name,
        phone_number = excluded.phone_number,
        avatar_reference = excluded.avatar_reference,
        updated_at = now();

  -- Self-service profile change audited in the same transaction.
  perform iam.append_audit_log(
    p_scope => 'platform',
    p_tenant_id => null,
    p_actor_user_id => v_user_id,
    p_event_code => 'iam.account.profile_updated',
    p_subject_type => 'account',
    p_subject_id => v_user_id::text,
    p_result => 'success',
    p_source => 'iam',
    p_tracking_id => v_user_id::text || ':' || extract(epoch from now())::text,
    p_after => jsonb_build_object(
      'given_name', v_given,
      'family_middle_name', v_family,
      'phone_number', v_phone
    )
  );

  return iam.get_my_platform_user_profile();
end;
$$;

revoke all on function iam.update_my_platform_user_profile(text, text, text, text) from public, anon;
grant execute on function iam.update_my_platform_user_profile(text, text, text, text) to authenticated;

-- Unified idempotency store for IAM commands (replaces per-command *_operations tables).
create table if not exists iam.idempotency_records (
  operation        text        not null,
  scope_id         text        not null,
  idempotency_key  text        not null,
  payload_hash     text,
  result           jsonb,
  created_at       timestamptz not null default now(),
  primary key (operation, scope_id, idempotency_key)
);

alter table iam.idempotency_records enable row level security;
revoke all on table iam.idempotency_records from public, anon, authenticated;

create or replace function iam._idempotency_find(
  p_operation text,
  p_scope_id text,
  p_key text,
  p_payload_hash text
)
returns iam.idempotency_records
language plpgsql
stable
security definer
set search_path = iam, pg_temp
as $$
declare
  v_row iam.idempotency_records;
begin
  select * into v_row
  from iam.idempotency_records r
  where r.operation = p_operation
    and r.scope_id = p_scope_id
    and r.idempotency_key = p_key;

  if found
     and p_payload_hash is not null
     and v_row.payload_hash is not null
     and v_row.payload_hash is distinct from p_payload_hash then
    raise exception 'IDEMPOTENCY_CONFLICT';
  end if;

  return v_row;
end;
$$;

create or replace function iam._idempotency_store(
  p_operation text,
  p_scope_id text,
  p_key text,
  p_payload_hash text,
  p_result jsonb
)
returns void
language sql
security definer
set search_path = iam, pg_temp
as $$
  insert into iam.idempotency_records (operation, scope_id, idempotency_key, payload_hash, result)
  values (p_operation, p_scope_id, p_key, p_payload_hash, p_result);
$$;

revoke all on function iam._idempotency_find(text, text, text, text) from public, anon, authenticated;
revoke all on function iam._idempotency_store(text, text, text, text, jsonb) from public, anon, authenticated;
